 1	# Nightly build service to pre-build devbox configuration
 2	# Builds packages overnight so they're ready when you upgrade
 3	{ pkgs, username, ... }:
 4	{
 5	  systemd.services.nix-nightly-build = {
 6	    description = "Nightly NixOS devbox configuration build";
 7	    serviceConfig = {
 8	      Type = "oneshot";
 9	      User = "root";
10	      # Low priority to avoid impacting system usage
11	      Nice = 19;
12	      IOSchedulingClass = "idle";
13	      # Timeout after 4 hours
14	      TimeoutStartSec = "4h";
15	    };
16	    path = with pkgs; [
17	      git
18	      nix
19	      nixos-rebuild
20	    ];
21	    script = ''
22	      set -euo pipefail
23	
24	      DOTFILES="/home/${username}/Projects/github.com/gotha/dotfiles"
25	      DATE=$(date +%Y-%m-%d)
26	      BUILD_DIR="/var/lib/nix-nightly/dotfiles-$DATE"
27	
28	      echo "Starting nightly build at $(date)"
29	
30	      # Clean up old builds (keep last 7 days)
31	      find /var/lib/nix-nightly -maxdepth 1 -name "dotfiles-*" -type d -mtime +7 -exec rm -rf {} \; 2>/dev/null || true
32	
33	      # Create build directory
34	      mkdir -p /var/lib/nix-nightly
35	      rm -rf "$BUILD_DIR"
36	      cp -r "$DOTFILES" "$BUILD_DIR"
37	      cd "$BUILD_DIR"
38	
39	      # Reset to clean state
40	      echo "Resetting to main branch..."
41	      git stash --include-untracked || true
42	      git checkout main
43	
44	      # Update flake inputs to latest versions
45	      echo "Updating flake.lock..."
46	      nix flake update 2>&1
47	
48	      # Build lucie config without switching
49	      # This populates /nix/store with all required packages
50	      echo "Building lucie configuration..."
51	      nixos-rebuild build --flake .#lucie 2>&1
52	
53	      # Create symlink to latest build
54	      ln -sfn "$BUILD_DIR" /var/lib/nix-nightly/latest
55	
56	      echo "Nightly build completed at $(date)"
57	      echo "flake.lock available at: $BUILD_DIR/flake.lock"
58	    '';
59	  };
60	
61	  systemd.timers.nix-nightly-build = {
62	    description = "Nightly NixOS devbox configuration build timer";
63	    wantedBy = [ "timers.target" ];
64	    timerConfig = {
65	      OnCalendar = "*-*-* 03:00:00";
66	      Persistent = true;
67	      RandomizedDelaySec = "30min";
68	    };
69	  };
70	}

